import Foundation

/// Rules that keep passwords and other secrets out of the history.
public struct PrivacyPolicy: Equatable, Sendable {
    /// Pasteboard types that apps use to mark content as secret or temporary
    /// (see nspasteboard.org). Content carrying any of them is never recorded.
    public static let markerTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
        "net.antelle.keeweb"
    ]

    /// Password managers whose copies are never recorded, whatever they put on the pasteboard.
    public static let defaultIgnoredApps: Set<String> = [
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.agilebits.onepassword-osx",
        "com.bitwarden.desktop",
        "com.apple.keychainaccess",
        "com.apple.Passwords",
        "org.keepassxc.keepassxc",
        "com.lastpass.LastPass",
        "com.dashlane.dashlanephonefinal",
        "in.sinew.Enpass-Desktop",
        "com.nordpass.macos.NordPass"
    ]

    public var extraIgnoredApps: Set<String>

    public init(extraIgnoredApps: Set<String> = []) {
        self.extraIgnoredApps = extraIgnoredApps
    }

    public var ignoredApps: Set<String> { Self.defaultIgnoredApps.union(extraIgnoredApps) }

    public func shouldIgnore(typeIdentifiers: [String], sourceBundleID: String?) -> Bool {
        if let id = sourceBundleID, ignoredApps.contains(id) { return true }
        return typeIdentifiers.contains { Self.markerTypes.contains($0) }
    }
}

/// Decides whether it is reasonable to contact a link's website to fetch its title.
public enum LinkPrivacy {
    static let secretParameterNames: Set<String> = [
        "token", "access_token", "id_token", "refresh_token", "auth", "key", "api_key", "apikey",
        "secret", "password", "pass", "pwd", "sig", "signature", "code", "session", "sessionid", "otp"
    ]

    public static func isSafeToFetch(_ url: URL) -> Bool {
        guard let components = URLComponents(url: url, resolvingAgainstBaseURL: false),
              let scheme = components.scheme?.lowercased(), scheme == "https" || scheme == "http",
              let host = components.host?.lowercased(), !host.isEmpty else { return false }
        if components.user != nil || components.password != nil { return false }
        if isLocal(host: host) { return false }
        let names = (components.queryItems ?? []).map { $0.name.lowercased() }
        return !names.contains { name in
            secretParameterNames.contains(name) || name.hasSuffix("token") || name.hasSuffix("secret")
        }
    }

    static func isLocal(host: String) -> Bool {
        if host == "localhost" || host.hasSuffix(".local") || host.hasSuffix(".localhost") || host.hasSuffix(".internal") { return true }
        let parts = host.split(separator: ".").compactMap { Int($0) }
        guard parts.count == 4 else { return host.contains(":") } // IPv6 literals are treated as local
        switch (parts[0], parts[1]) {
        case (10, _), (127, _), (0, _): return true
        case (169, 254), (192, 168): return true
        case (172, 16...31): return true
        case (100, 64...127): return true
        default: return false
        }
    }
}
